CREATE OR REPLACE FUNCTION zoi.ensure_listing_slug()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare base text; cand text; n int := 0;
begin
  if new.slug is not null and length(new.slug) > 0 then
    return new;
  end if;
  begin
    if new.canonical_path is not null and length(new.canonical_path) > 0 then
      base := substring(new.canonical_path from '^/[^/]+/(.+)$');
    end if;
    if base is null or length(base) = 0 then
      base := zoi.seo_slug(coalesce(new.name,'') || '-' || coalesce(new.city,''));
    end if;
    if base is null or length(base) = 0 then
      return new;                              -- cannot derive; keep today's behavior
    end if;
    cand := base;
    while exists (select 1 from zoi.listings x where x.slug = cand and x.id <> new.id) loop
      n := n + 1;
      cand := base || '-' || n;
      if n > 50 then
        cand := base || '-' || substr(replace(new.id::text,'-',''),1,8);
        exit;
      end if;
    end loop;
    new.slug := cand;
  exception when others then
    null;                                      -- never break the write
  end;
  return new;
end
$function$

CREATE OR REPLACE FUNCTION zoi.auto_seo_fill()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE
  v_cat_slug text;
  v_cat_label text;
  v_slug text;
  v_title text;
  v_desc text;
BEGIN
  IF NEW.primary_category_id IS NOT NULL THEN
    SELECT c.slug, c.label_en INTO v_cat_slug, v_cat_label
    FROM zoi.categories c WHERE c.id = NEW.primary_category_id;
  END IF;

  v_slug := coalesce(NEW.slug, zoi.seo_slug(NEW.name || '-' || coalesce(NEW.city,'')));

  IF NEW.schema_type IS NULL OR length(NEW.schema_type)=0 THEN
    NEW.schema_type := zoi.schema_type(NEW.entity_type, coalesce(v_cat_slug,''));
  END IF;

  IF NEW.canonical_path IS NULL OR length(NEW.canonical_path)=0 THEN
    NEW.canonical_path := '/' || NEW.entity_type || '/' || v_slug;
  END IF;

  IF NEW.meta_title IS NULL OR length(NEW.meta_title)=0 THEN
    v_title := NEW.name
      || coalesce(' — ' || zoi.seo_pluralize(v_cat_label), '')
      || coalesce(' in ' || NEW.city, '')
      || ' | Zoi';
    IF length(v_title) > 66 THEN
      v_title := NEW.name || coalesce(' in ' || NEW.city, '') || ' | Zoi';
    END IF;
    IF length(v_title) > 66 THEN
      v_title := left(NEW.name, 60) || ' | Zoi';
    END IF;
    NEW.meta_title := v_title;
  END IF;

  IF NEW.meta_description IS NULL OR length(NEW.meta_description)=0 THEN
    IF NEW.description IS NOT NULL AND length(NEW.description) >= 30
       AND NEW.description !~* '^https?://' THEN
      v_desc := left(NEW.description, 158);
    ELSE
      v_desc := NEW.name
        || coalesce(' in ' || NEW.city, '')
        || coalesce(', ' || NEW.country, '')
        || '. Listed on Zoi, the Greek community directory.';
    END IF;
    NEW.meta_description := v_desc;
  END IF;

  RETURN NEW;
END$function$

CREATE OR REPLACE FUNCTION zoi.skip_noop_listing_update()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'zoi', 'public'
AS $function$
BEGIN
  IF (to_jsonb(NEW) - 'updated_at') = (to_jsonb(OLD) - 'updated_at') THEN
    RETURN NULL;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION zoi.publish_gate(p_name text, p_entity_type text, p_category bigint, p_city text, p_country text, p_phone text, p_address text, p_website text)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
  v_name  text := coalesce(btrim(p_name),'');
  v_alpha text;
  v_et    text := lower(coalesce(btrim(p_entity_type),''));
  v_fails text[] := array[]::text[];
  v_warn  text[] := array[]::text[];
  v_lq    jsonb;
  v_physical boolean;
  v_any_channel boolean;
BEGIN
  v_alpha := regexp_replace(v_name,'[^[:alpha:]]','','g');
  -- Entity types that exist at a physical place. Creators, vendors (online shops),
  -- artists and travel listings are legitimately location-less.
  v_physical := v_et IN ('business','church','school','venue','sports','professional');
  v_any_channel := coalesce(btrim(p_website),'') <> ''
                OR coalesce(btrim(p_phone),'')   <> ''
                OR coalesce(btrim(p_address),'') <> '';

  -- 1. NAME INTEGRITY
  IF v_name = '' THEN v_fails := array_append(v_fails,'name_empty'); END IF;
  IF length(v_alpha) < 2 THEN v_fails := array_append(v_fails,'name_no_real_letters'); END IF;
  IF length(v_name) > 120 THEN v_fails := array_append(v_fails,'name_too_long'); END IF;

  -- 2. SCRAPE ARTEFACTS
  -- Listicle: "Top 10 Best ..." — number must be followed by a word, so "Best 92.6" (radio) is safe.
  IF v_name ~* '(^|[^[:alpha:]])(top|best)[[:space:]]+[0-9]{1,3}[[:space:]]+[[:alpha:]]' THEN
    v_fails := array_append(v_fails,'listicle_title');
  END IF;
  IF v_name ~* '(yelp|tripadvisor|wikipedia|google maps|facebook\.com|instagram\.com|linkedin\.com)' THEN
    v_fails := array_append(v_fails,'platform_title');
  END IF;
  IF v_name ~* 'near me$|^the [0-9]+ (best|top) |updated [0-9]{4}|^[0-9]+ (best|top) ' THEN
    v_fails := array_append(v_fails,'seo_title');
  END IF;
  -- Pipe alone is NOT junk (real names like "Astra Report | WNTN 1550 AM" exist).
  -- Only flag a trailing " - <platform>" or " | <platform>" suffix.
  IF v_name ~* '[[:space:]][-|][[:space:]]*(yelp|tripadvisor|facebook|instagram|menu|home|official site)[[:space:]]*$' THEN
    v_fails := array_append(v_fails,'page_title_artefact');
  END IF;
  IF lower(v_name) ~ '^(home|about|about us|contact|contact us|menu|untitled|test|n/?a|null|none|unknown|tbd|click here|read more|business directory)$' THEN
    v_fails := array_append(v_fails,'nav_or_placeholder_name');
  END IF;

  -- 3. CLASSIFICATION
  IF p_category IS NULL THEN v_fails := array_append(v_fails,'missing_category'); END IF;

  -- 4. LOCATION — only required for physical entity types, and only when there is
  -- also no contact channel to identify the entity by.
  IF v_physical
     AND coalesce(btrim(p_city),'') = ''
     AND coalesce(btrim(p_country),'') = ''
     AND NOT v_any_channel THEN
    v_fails := array_append(v_fails,'no_location_and_no_contact');
  END IF;

  -- 5. Existing scorer's hard-junk judgement
  v_lq := zoi.listing_quality(p_name,p_phone,p_address,p_website,p_category,p_entity_type);
  IF (v_lq->>'ok')::boolean IS FALSE THEN
    v_fails := array_append(v_fails,'listing_quality_fail');
  END IF;

  -- 6. WARNINGS — never block; these feed the enrichment queue.
  IF NOT v_any_channel THEN v_warn := array_append(v_warn,'no_contact_channel'); END IF;
  IF coalesce(btrim(p_city),'')='' THEN v_warn := array_append(v_warn,'no_city'); END IF;
  IF coalesce(btrim(p_country),'')='' THEN v_warn := array_append(v_warn,'no_country'); END IF;

  RETURN jsonb_build_object(
    'ok', (array_length(v_fails,1) IS NULL),
    'fails', to_jsonb(v_fails),
    'warnings', to_jsonb(v_warn),
    'quality_score', (v_lq->>'score')::int
  );
END;
$function$

CREATE OR REPLACE FUNCTION zoi.tg_apply_publish_gate()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare v_gate jsonb;
begin
 if new.publish_status is null or new.publish_status in ('draft','published') then
  v_gate:=zoi.publish_gate(new.name,new.entity_type,new.primary_category_id,new.city,new.country,new.phone,new.address,new.website);
  if new.publish_status is distinct from 'draft' then
   if (v_gate->>'ok')::boolean then new.publish_status:='published';
   else new.publish_status:='pending_review';end if;
  end if;
  new.profile:=coalesce(new.profile,'{}'::jsonb)||jsonb_build_object('gate',jsonb_build_object(
   'ok',v_gate->'ok','fails',v_gate->'fails','warnings',v_gate->'warnings',
   'checked_at',to_char(now() at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"')));
  new.completeness_score:=round(((v_gate->>'quality_score')::numeric/100.0),3);
 end if;
 return new;
end;
$function$

CREATE OR REPLACE FUNCTION zoi.guard_listing_quality_receipts()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE prior_receipt jsonb;
BEGIN
 IF TG_OP='UPDATE' THEN prior_receipt:=OLD.profile->'_coverage';END IF;
 IF (current_user IN('anon','authenticated') OR current_setting('request.jwt.claim.role',true) IN('anon','authenticated') OR coalesce(nullif(current_setting('request.jwt.claims',true),''),'{}')::jsonb->>'role' IN('anon','authenticated')) AND NEW.profile->'_coverage' IS DISTINCT FROM prior_receipt THEN RAISE EXCEPTION 'quality_receipts_service_only';END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION zoi.seo_name(p_name text, p_city text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE PARALLEL SAFE
AS $function$
DECLARE n text:=zoi.seo_text(p_name); c text:=zoi.seo_text(p_city);
BEGIN
 IF c<>'' AND pg_catalog.length(n)>pg_catalog.length(c)+1 AND pg_catalog.right(n,pg_catalog.length(c)+1)=' '||c THEN
  RETURN pg_catalog.left(n,pg_catalog.length(n)-pg_catalog.length(c)-1);
 END IF;
 RETURN n;
END;
$function$

CREATE OR REPLACE FUNCTION zoi.listing_quality(p_name text, p_phone text, p_address text, p_website text, p_category bigint, p_entity_type text)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare
  v_score int := 60;
  v_reasons text[] := array[]::text[];
  v_name text := coalesce(btrim(p_name), '');
  v_phone text := coalesce(btrim(p_phone), '');
  v_addr text := coalesce(btrim(p_address), '');
  v_web text := coalesce(btrim(p_website), '');
  v_et text := lower(coalesce(btrim(p_entity_type), ''));
  v_tokens int; v_alpha text;
  v_has_contact boolean; v_any_channel boolean;
  v_is_person boolean; v_needs_physical boolean;
  v_biz_token boolean; v_looks_personal boolean; v_allcaps_surname boolean;
  v_identifiable boolean; v_hard_junk boolean := false;
  v_threshold int := 55;
begin
  v_alpha := regexp_replace(v_name, '[^[:alpha:]]', '', 'g');
  v_tokens := array_length(regexp_split_to_array(v_name, '\s+'), 1);
  if v_name = '' then v_tokens := 0; end if;

  v_is_person := v_et in ('professional','creator','artist');
  v_needs_physical := v_et in ('business','church','school','venue','organization','sports');

  v_biz_token := v_name ~* '(restaurant|taverna|taverne|tavern|ouzeri|mezze?|meze|cuisine|cafe|caf[eé]|kafe|kafenio|coffee|bakery|patisserie|pastry|pastries|grill|kitchen|kouzina|koyzina|estiatorio|psistaria|deli|market|bazaar|grocery|foods?|seafood|diner|pita|gardens|honey|farm|mastiha|apothecary|magazine|bar|bistro|pizz|gyro|souvlaki|club|hotel|inn|resort|room|studio|salon|spa|clinic|center|centre|institute|academy|school|college|church|kirche|orthodox|cathedral|parish|monastery|temple|shrine|theotokos|annunciation|dormition|nativity|ascension|assumption|transfiguration|filoptochos|brotherhood|pancyprian|associat|society|federation|foundation|council|union|chamber|company|co\.|corp|inc\.?|ltd|llc|gmbh|group|network|television|world|services|solutions|consult|agency|law|legal|medical|dental|pharmac|insurance|realty|real estate|travel|tours|imports|exports|trading|wines|winery|brewery|distillery|productions|media|radio|fm|tv|ert|gallery|museum|theatre|theater|festival|function|expo|games|fc|f\.c\.|football|soccer|hellenic|greek|grecian|hellas|athenian|mitilini|parthenon|delfini|myth|casa|saint|st\.|holy|cosmos|concept|grove|olive|blue)';

  -- ALLCAPS "SURNAME FIRSTNAME" Greek scrape junk (the named hard pattern)
  v_allcaps_surname := (not v_biz_token) and v_tokens between 2 and 3
    and v_name = upper(v_name) and v_name ~ '^[[:upper:]]{2,}([[:space:]\-]+[[:upper:]]{2,}){1,2}$';
  -- Titlecase personal-name shape: SOFT signal only (too many brand collisions)
  v_looks_personal := (not v_biz_token) and v_tokens between 2 and 3
    and v_name ~ '^[[:upper:]][[:lower:]]+([[:space:]\-]+[[:upper:]][[:lower:]]+){1,2}$';

  v_has_contact := (v_phone <> '' or v_addr <> '');
  v_any_channel := (v_phone <> '' or v_addr <> '' or v_web <> '');

  v_identifiable := v_any_channel or v_biz_token or (coalesce(v_tokens,0) >= 2) or v_is_person;

  -- HARD JUNK NAME CHECKS
  if v_name = '' then
    v_score := 0; v_hard_junk := true; v_reasons := array_append(v_reasons, 'name_empty'::text);
  elsif v_name ~ '^[0-9[:space:][:punct:]]+$' then
    v_score := 0; v_hard_junk := true; v_reasons := array_append(v_reasons, 'name_digits_or_symbols_only'::text);
  elsif length(v_alpha) < 2 then
    v_score := 0; v_hard_junk := true; v_reasons := array_append(v_reasons, 'name_no_real_letters'::text);
  elsif v_tokens = 1 and length(v_name) <= 3 and not v_any_channel then
    -- single very short token AND no way to find it = junk; with contact it's identifiable
    v_score := v_score - 40; v_hard_junk := true;
    v_reasons := array_append(v_reasons, 'name_single_short_token_no_contact'::text);
  end if;

  -- BUSINESS as bare ALLCAPS personal name with NO contact = junk (named pattern)
  if v_et = 'business' and v_allcaps_surname and not v_any_channel then
    v_score := v_score - 50; v_hard_junk := true;
    v_reasons := array_append(v_reasons, 'business_allcaps_personal_name_no_contact'::text);
  end if;

  -- SOFT SIGNALS
  if v_phone <> '' then v_score := v_score + 10; v_reasons := array_append(v_reasons, 'has_phone'::text); end if;
  if v_addr  <> '' then v_score := v_score + 10; v_reasons := array_append(v_reasons, 'has_address'::text); end if;
  if v_web   <> '' then v_score := v_score + 8;  v_reasons := array_append(v_reasons, 'has_website'::text); end if;
  if v_biz_token  then v_score := v_score + 5;  v_reasons := array_append(v_reasons, 'has_business_keyword'::text); end if;

  -- Titlecase personal-name business with no contact: soft warning only
  if v_et = 'business' and v_looks_personal and not v_any_channel then
    v_reasons := array_append(v_reasons, 'business_name_may_be_personal'::text);
  end if;

  if p_category is not null then
    v_score := v_score + 8; v_reasons := array_append(v_reasons, 'has_category'::text);
  else
    v_score := v_score - 6; v_reasons := array_append(v_reasons, 'missing_category'::text);
  end if;

  if not v_has_contact then
    if v_is_person then
      v_reasons := array_append(v_reasons, 'person_no_physical_contact_ok'::text);
    elsif v_web <> '' then
      v_score := v_score - 4; v_reasons := array_append(v_reasons, 'no_phone_or_address_website_only'::text);
    else
      v_score := v_score - 8; v_reasons := array_append(v_reasons, 'thin_contact_needs_enrichment'::text);
    end if;
  end if;

  -- FLOOR: identifiable, non-junk listings stay published despite incompleteness
  if not v_hard_junk and v_identifiable and v_score < v_threshold then
    v_score := v_threshold;
  end if;

  if v_score < 0 then v_score := 0; end if;
  if v_score > 100 then v_score := 100; end if;

  return jsonb_build_object(
    'score', v_score, 'ok', (v_score >= v_threshold),
    'threshold', v_threshold, 'reasons', to_jsonb(v_reasons));
end;
$function$

